<?php
declare(strict_types=1);function x1_security_headers():void{if(headers_sent())return;header('X-Content-Type-Options: nosniff');header('X-Frame-Options: DENY');header('Referrer-Policy: same-origin');header('Permissions-Policy: camera=(), microphone=(), geolocation=()');header("Content-Security-Policy: default-src 'self'; img-src 'self' data:; style-src 'self' 'unsafe-inline'; script-src 'self'; connect-src 'self'; frame-ancestors 'none'; base-uri 'self'; form-action 'self'");}function x1_app_key():string{$raw=(string)x1_env('X1_APP_KEY','');if($raw==='')return'';if(str_starts_with($raw,'base64:')){$d=base64_decode(substr($raw,7),true);if($d!==false&&strlen($d)>=32)return substr($d,0,32);}return hash('sha256',$raw,true);}function x1_encrypt_secret(string $plain):string{if($plain==='')return'';$key=x1_app_key();if($key==='')throw new RuntimeException('X1_APP_KEY is not configured');$iv=random_bytes(12);$tag='';$ct=openssl_encrypt($plain,'aes-256-gcm',$key,OPENSSL_RAW_DATA,$iv,$tag);if($ct===false)throw new RuntimeException('Encryption failed');return'v1:'.base64_encode($iv.$tag.$ct);}function x1_decrypt_secret(string $blob):string{if($blob==='')return'';if(!str_starts_with($blob,'v1:'))throw new RuntimeException('Unsupported secret format');$raw=base64_decode(substr($blob,3),true);if($raw===false||strlen($raw)<29)throw new RuntimeException('Invalid secret');$iv=substr($raw,0,12);$tag=substr($raw,12,16);$ct=substr($raw,28);$key=x1_app_key();if($key==='')throw new RuntimeException('X1_APP_KEY is not configured');$pt=openssl_decrypt($ct,'aes-256-gcm',$key,OPENSSL_RAW_DATA,$iv,$tag);if($pt===false)throw new RuntimeException('Decryption failed');return $pt;}function x1_client_ip():string{return substr((string)($_SERVER['REMOTE_ADDR']??''),0,64);}function x1_login_key(string $username):string{return hash('sha256',strtolower(trim($username)).'|'.x1_client_ip());}function x1_login_allowed(string $username):array{$db=x1_db();if(!$db)return['allowed'=>true,'remaining'=>null,'locked_until'=>0];$key=x1_login_key($username);$row=x1_db_one('SELECT * FROM login_attempts WHERE key=?',[$key]);$now=time();if(!$row)return['allowed'=>true,'remaining'=>5,'locked_until'=>0];if((int)$row['locked_until']>$now)return['allowed'=>false,'remaining'=>0,'locked_until'=>(int)$row['locked_until']];$remaining=max(0,5-(int)$row['attempts']);return['allowed'=>true,'remaining'=>$remaining,'locked_until'=>0];}function x1_login_fail(string $username):void{$db=x1_db();if(!$db)return;$key=x1_login_key($username);$now=time();$row=x1_db_one('SELECT * FROM login_attempts WHERE key=?',[$key]);$attempts=$row?(int)$row['attempts']+1:1;$first=$row?(int)$row['first_at']:$now;if($now-$first>900){$attempts=1;$first=$now;}$locked=$attempts>=5?$now+900:0;x1_db_exec('INSERT INTO login_attempts(key,attempts,first_at,last_at,locked_until) VALUES(?,?,?,?,?) ON CONFLICT(key) DO UPDATE SET attempts=excluded.attempts,first_at=excluded.first_at,last_at=excluded.last_at,locked_until=excluded.locked_until',[$key,$attempts,$first,$now,$locked]);}function x1_login_clear(string $username):void{if(x1_db())x1_db_exec('DELETE FROM login_attempts WHERE key=?',[x1_login_key($username)]);}function x1_role_rank(string $role):int{return['readonly'=>10,'operator'=>20,'admin'=>30,'owner'=>40][$role]??0;}function x1_current_role():string{x1_admin_start();return(string)($_SESSION['role']??'readonly');}function x1_require_role(string $minimum):void{x1_require_admin();if(x1_role_rank(x1_current_role())<x1_role_rank($minimum)){http_response_code(403);exit('Forbidden');}}